-- Tabela CID-10 (OMS, versão brasileira do DATASUS, arquivo CID10CSV.zip de
-- 2008): 2045 categorias e 12188 subcategorias. Referência pública, igual para
-- todas as clínicas: serve à busca de diagnóstico por código ou descrição na
-- ficha de atendimento. O diagnóstico salvo continua em encounter_diagnoses
-- (código + descrição copiados), então editar esta tabela não altera
-- prontuários já registrados.

create table if not exists public.cid10_codes (
  code text primary key,
  code_key text not null unique,
  category text not null,
  description text not null,
  is_category boolean not null,
  search_text text not null
);

comment on table public.cid10_codes is
  'CID-10 (DATASUS). code no formato de escrita (A00, A00.0); code_key sem ponto e minúsculo; search_text sem acentos, para busca.';

create index if not exists cid10_codes_search_trgm_idx
  on public.cid10_codes using gin (search_text gin_trgm_ops);

alter table public.cid10_codes enable row level security;

drop policy if exists "cid10_codes_read" on public.cid10_codes;
create policy "cid10_codes_read"
on public.cid10_codes for select
to authenticated
using (true);

revoke insert, update, delete on public.cid10_codes from anon, authenticated;
grant select on public.cid10_codes to authenticated;

-- Busca por código (com ou sem ponto) ou por palavras da descrição. O termo
-- chega já normalizado pelo app (minúsculo, sem acentos); cada palavra
-- precisa aparecer. Código exato e prefixo de código vêm primeiro.
create or replace function public.search_cid10(
  p_query text,
  p_limit integer default 20
)
returns table (code text, description text, is_category boolean)
language sql
stable
set search_path = pg_catalog, public
as $$
  with term as (
    select
      btrim(coalesce(p_query, '')) as q,
      replace(btrim(coalesce(p_query, '')), '.', '') as code_q
  )
  select c.code, c.description, c.is_category
  from public.cid10_codes c, term t
  where char_length(t.q) >= 2
    and (
      c.code_key like t.code_q || '%'
      or (
        select bool_and(c.search_text like '%' || word || '%')
        from unnest(string_to_array(t.q, ' ')) as word
        where word <> ''
      )
    )
  order by
    case
      when c.code_key = t.code_q then 0
      when c.code_key like t.code_q || '%' then 1
      when c.search_text like t.q || '%' then 2
      else 3
    end,
    c.code_key
  limit least(greatest(coalesce(p_limit, 20), 1), 50);
$$;

revoke all on function public.search_cid10(text, integer) from public, anon;
grant execute on function public.search_cid10(text, integer) to authenticated;

on conflict (code) do update
set description = excluded.description,
    category = excluded.category,
    is_category = excluded.is_category,
    search_text = excluded.search_text;
